}

// Helper: card
function addCard(slide, x, y, w, h, color, shadow) {
  slide.addShape("roundRect", {
    x, y, w, h,
    fill: { color: P.accent },
    rectRound: 0.1,
    shadow: shadow ? { type: "outer", blur: 5, offset: 2, color: "000000", opacity: 0.08 } : undefined
  });
}

