import json, sys
from pptx import Presentation
from pptx.util import Inches

prs = Presentation("{{SESSION_PATH}}/data/Chill_冷柜_路演PPT_v2.pptx")

results = {"slides": len(prs.slides), "details": []}
for i, slide in enumerate(prs.slides):
    info = {
        "page": i + 1,
        "shapes": len(slide.shapes),
        "has_image": any(s.shape_type == 13 for s in slide.shapes),
        "items": []
    }
    for sh in slide.shapes:
        if sh.has_text_frame:
            text = sh.text_frame.text[:80]
            if text.strip():
                info["items"].append({"type": "text", "content": text})
        elif sh.shape_type == 13:
            info["items"].append({"type": "image", "name": sh.name})
        else:
            info["items"].append({"type": "shape", "name": sh.shape_type})
    results["details"].append(info)

with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(results, f, ensure_ascii=False, indent=2)

# Quick summary
for d in results["details"]:
    imgs = sum(1 for x in d["items"] if x["type"] == "image")
    print(f"Slide {d['page']:2d}: {d['shapes']:2d} shapes, {imgs} images")

