slides_html = """
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=1280, initial-scale=1.0">
<link href="https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { margin:0; padding:0; box-sizing:border-box; }
body { background:#000; color:#f5f5f7; -webkit-font-smoothing:antialiased; font-family:'DM Sans','Microsoft YaHei',sans-serif; }
.slide { width:1280px; height:720px; background:#000; padding:28px; display:flex; flex-direction:column; margin:0 auto 60px; }
.grid { display:grid; gap:6px; flex:1; }
.card { background:linear-gradient(145deg,#1a1a1a,#0d0d0d); border-radius:20px; padding:24px 26px; display:flex; flex-direction:column; justify-content:center; position:relative; overflow:hidden; }
.num { font-family:'Sora','Microsoft YaHei',sans-serif; font-weight:800; letter-spacing:-0.03em; line-height:1; }
.label { font-family:'DM Sans','Microsoft YaHei',sans-serif; font-weight:500; color:#888; line-height:1.25; }

/* Hero */
.card-hero { justify-content:center; padding:28px 32px; }
.card-hero::before { content:''; position:absolute; top:0; left:0; right:0; height:4px; background:linear-gradient(90deg,#2997ff,#64d2ff,#2997ff); border-radius:20px 20px 0 0; }
.hero-tagline { font-family:'Sora','Microsoft YaHei',sans-serif; font-size:38px; font-weight:700; color:#f5f5f7; letter-spacing:-0.03em; line-height:1.15; }
.hero-sub { font-family:'Sora','Microsoft YaHei',sans-serif; font-size:38px; font-weight:700; color:#888; letter-spacing:-0.03em; line-height:1.15; }
.hero-eyebrow { font-family:'DM Sans','Microsoft YaHei',sans-serif; font-size:12px; font-weight:600; color:#64d2ff; text-transform:uppercase; letter-spacing:0.08em; margin-bottom:10px; }
.hero-date { font-family:'DM Sans','Microsoft YaHei',sans-serif; font-size:12px; font-weight:500; color:#555; margin-top:10px; }

/* Stat */
.card-stat-blue { background:linear-gradient(145deg,#0a1628,#0d0d0d); }
.card-stat-blue::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(41,151,255,0.08) 0%,transparent 70%); }
.card-stat-green { background:linear-gradient(145deg,#0a1e0a,#0d0d0d); }
.card-stat-green::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(48,209,88,0.08) 0%,transparent 70%); }
.card-stat-purple { background:linear-gradient(145deg,#1a0a28,#0d0d0d); }
.card-stat-purple::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(191,90,242,0.08) 0%,transparent 70%); }
.card-stat-cyan { background:linear-gradient(145deg,#0a1a20,#0d0d0d); }
.card-stat-cyan::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(100,210,255,0.08) 0%,transparent 70%); }
.card-stat-coral { background:linear-gradient(145deg,#1e0a0a,#0d0d0d); }
.card-stat-coral::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(255,69,58,0.08) 0%,transparent 70%); }
.card-stat-amber { background:linear-gradient(145deg,#1e140a,#0d0d0d); }
.card-stat-amber::after { content:''; position:absolute; top:-30px; right:-30px; width:140px; height:140px; border-radius:50%; background:radial-gradient(circle,rgba(255,159,10,0.08) 0%,transparent 70%); }

.stat-num-blue { font-size:44px; color:#2997ff; margin-bottom:4px; }
.stat-num-green { font-size:44px; color:#30d158; margin-bottom:4px; }
.stat-num-purple { font-size:44px; color:#bf5af2; margin-bottom:4px; }
.stat-num-cyan { font-size:44px; color:#64d2ff; margin-bottom:4px; }
.stat-num-coral { font-size:44px; color:#ff453a; margin-bottom:4px; }
.stat-num-amber { font-size:44px; color:#ff9f0a; margin-bottom:4px; }
.stat-label { font-size:13px; line-height:1.3; }
.stat-sub { font-size:11px; color:#555; margin-top:6px; }

/* Quote */
.card-quote { background:linear-gradient(135deg,#1c1c1e,#111); text-align:center; padding:24px 32px; }
.quote-text { font-family:'Sora','Microsoft YaHei',sans-serif; font-size:22px; font-weight:600; color:#f5f5f7; letter-spacing:-0.01em; line-height:1.4; }
.quote-text em { color:#30d158; font-style:normal; }

/* Highlight */
.card-highlight { text-align:center; justify-content:center; align-items:center; }
.card-highlight .num { font-size:64px; color:#fff; margin-bottom:4px; }
.card-highlight .label { font-size:16px; color:rgba(255,255,255,0.85); font-weight:600; }
.card-highlight .sub { font-size:12px; color:rgba(255,255,255,0.5); margin-top:6px; }
.hl-green { background:linear-gradient(145deg,#059669,#34d399,#6ee7b7); }
.hl-blue { background:linear-gradient(145deg,#1d4ed8,#3b82f6,#93c5fd); }
.hl-cyan { background:linear-gradient(145deg,#0e7490,#06b6d4,#67e8f9); }

/* Badge */
.badge { display:inline-flex; align-items:center; gap:5px; border-radius:100px; padding:4px 12px; margin-bottom:8px; width:fit-content; font-size:11px; font-weight:600; }
.badge-blue { background:rgba(41,151,255,0.15); color:#2997ff; }
.badge-green { background:rgba(48,209,88,0.15); color:#30d158; }
.badge-purple { background:rgba(191,90,242,0.15); color:#bf5af2; }
.badge-cyan { background:rgba(100,210,255,0.15); color:#64d2ff; }

/* Pills */
.pills-wrap { display:flex; flex-wrap:wrap; gap:0; margin-top:4px; }
.pill { display:inline-block; font-size:10px; font-weight:600; color:#aaa; background:rgba(255,255,255,0.08); border-radius:100px; padding:3px 9px; margin:2px 2px 2px 0; white-space:nowrap; }

/* Bar chart */
.bar-group { display:flex; flex-direction:column; align-items:center; gap:4px; flex:1; }
.bar-val { font-family:'Sora',sans-serif; font-size:10px; font-weight:700; color:#fff; }
.bar { width:100%; border-radius:6px; }
.bar-lbl { font-size:10px; font-weight:600; color:#555; text-transform:uppercase; letter-spacing:0.05em; }

/* Page number */
.page-num { font-size:11px; color:#333; text-align:right; margin-top:8px; font-family:'DM Sans',sans-serif; }

/* Category */
.category-name { font-family:'Sora','Microsoft YaHei',sans-serif; font-size:13px; font-weight:700; letter-spacing:-0.01em; margin-bottom:4px; }
.cat-blue { color:#2997ff; }
.cat-cyan { color:#64d2ff; }
.cat-green { color:#30d158; }
.cat-purple { color:#bf5af2; }
.cat-coral { color:#ff453a; }
.cat-amber { color:#ff9f0a; }

/* Mode cards */
.mode-card { padding:20px 24px; }
.mode-icon { width:32px; height:32px; border-radius:50%; margin-bottom:8px; }
.mode-title { font-family:'DM Sans','Microsoft YaHei',sans-serif; font-size:18px; font-weight:700; color:#f5f5f7; margin-bottom:4px; }
.mode-temp { font-size:12px; font-weight:600; margin-bottom:6px; }
.mode-desc { font-size:12px; color:#888; line-height:1.4; }
</style>
</head>
<body>
